package org.sleepwell.app;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.activity.*;import java.util.*;import org.json.*;
/** User-started local semantic classification, never a picture hash or proof of real-world liveness. */
public final class ObjectRecognitionActivity extends ComponentActivity {
 static final int FALLBACK=RESULT_FIRST_USER;private String request,run,mode,error="",status="Camera stays off until you start.";private int unit;private ObjectTarget target;private boolean resumed,detected;private long generation,started;private ObjectCamera camera;private ObjectHold hold;private TextView live;private Dialog choices;private final Handler handler=new Handler(Looper.getMainLooper());
 static Intent configure(Activity a,ObjectTarget target,String request){try{return RecordUi.intent(a,ObjectRecognitionActivity.class).putExtra("mode","configure").putExtra("request",request).putExtra("objectTarget",ObjectTargetJson.encode(target==null?ObjectTarget.DEFAULT:target).toString());}catch(JSONException impossible){throw new IllegalStateException(impossible);}}
 static Intent challenge(Activity a,ObjectTarget target,String run,int unit,String request){return configure(a,target,request).putExtra("mode","challenge").putExtra("run",run).putExtra("unit",unit);}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);setResult(RESULT_CANCELED);try{request=getIntent().getStringExtra("request");if(request==null||!UUID.fromString(request).toString().equals(request))throw new IllegalArgumentException();mode=getIntent().getStringExtra("mode");if(!Set.of("configure","challenge").contains(mode))throw new IllegalArgumentException();target=ObjectTargetJson.decode(new JSONObject(getIntent().getStringExtra("objectTarget")));run=mode.equals("configure")?request:getIntent().getStringExtra("run");unit=mode.equals("configure")?0:getIntent().getIntExtra("unit",-1);if(run==null||run.isBlank()||run.length()>128||unit<0)throw new IllegalArgumentException();if(saved!=null){if(mode.equals("configure"))target=ObjectTargetJson.decode(new JSONObject(saved.getString("objectTarget")));error=saved.getString("error","");status="Camera paused. Start a fresh attempt when ready.";}}catch(Exception invalid){finish();return;}hold=new ObjectHold(target);if(mode.equals("challenge")){setShowWhenLocked(true);setTurnScreenOn(true);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}getOnBackPressedDispatcher().addCallback(this,new OnBackPressedCallback(true){public void handleOnBackPressed(){back();}});render();}
 private boolean current(){if(!resumed||isFinishing()||isDestroyed())return false;if(mode.equals("configure"))return true;try{if(!AlarmService.current(this,run)||Prefs.number(this,"challengeCompleted",-1)!=unit)return false;JSONObject raw=new JSONObject(Prefs.text(this,"active_alarm","{}"));Alarm active=Alarm.read(raw);ChallengeRoutine.Position position=active.challenges().at(unit);if(position==null||!position.task.type.equals("Object recognition"))return false;ObjectTarget live=ObjectTargetJson.decode(raw.getJSONArray("routine").getJSONObject(position.index).get("objectTarget"));return live.key().equals(target.key());}catch(Exception invalid){return false;}}
 private final Runnable verify=new Runnable(){public void run(){if(!resumed)return;if(!current()){stop();setResult(RESULT_CANCELED);finish();return;}if(camera!=null&&SystemClock.elapsedRealtime()-started>=30000){stop();status="Attempt ended";error="The 30-second camera attempt ended. Retry or use Math.";render();}handler.postDelayed(this,250);}};
 private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,mode.equals("configure")?"Choose an object":"Find your object",this::back);Design.space(body,12);if(mode.equals("configure")){Design.item(body,"camera","Model target",target.label(),this::choose);Design.space(body,10);}else{Design.text(body,target.label(),27,600,Design.BROWN);Design.space(body,8);}Design.text(body,"Show this object clearly to the rear camera in good light. Fill the center with one object and hold it steady.",14,400,Design.MUTED);Design.space(body,12);FrameLayout frame=new FrameLayout(this);frame.setBackground(Design.shape(this,Design.SOFT,18));frame.setClipToOutline(true);frame.setContentDescription("Experimental object camera preview");if(camera!=null){View preview=camera.preview();if(preview.getParent() instanceof ViewGroup parent)parent.removeView(preview);frame.addView(preview,new FrameLayout.LayoutParams(-1,-1));}else{TextView empty=Design.text(this,detected?"Target detected in test":"Rear camera paused",16,500,Design.MUTED);empty.setGravity(Gravity.CENTER);frame.addView(empty,new FrameLayout.LayoutParams(-1,-1));}body.addView(frame,new LinearLayout.LayoutParams(-1,Design.dp(this,264)));Design.space(body,12);live=Design.text(body,status,14,500,Design.BROWN);live.setContentDescription("Object recognition status");live.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);if(camera==null){ObjectCameraAccess.Status permission=ObjectCameraAccess.status(this);String label=permission==ObjectCameraAccess.Status.NEEDED?"Allow object camera":permission==ObjectCameraAccess.Status.SETTINGS?"Open camera settings":"Start object camera";Button start=Design.button(body,label,true,this::startPressed);if(permission==ObjectCameraAccess.Status.UNSUPPORTED){start.setEnabled(false);Design.text(body,"A rear camera is unavailable. Choose Math instead.",13,400,Design.MUTED);}}else Design.button(body,"Pause camera",false,()->{stop();status="Camera paused. Start a new attempt when ready.";render();});Design.space(body,12);Design.text(body,"Experimental on-device EfficientNet-Lite0 image classification. Scores may be wrong, especially in dim light. Photos or screens may pass: this is not liveness, identity or authentication.",12,400,Design.MUTED);Design.space(body,8);Design.text(body,"Bundled TensorFlow Apache2.0 model ·1000 ImageNet labels · no images saved or uploaded. Math is always available if recognition does not work.",12,400,Design.MUTED);LinearLayout footer=RecordUi.footer(body);if(!error.isEmpty()){Design.text(footer,error,12,500,0xffa93919).setContentDescription("Object camera error");}if(mode.equals("configure"))Design.button(footer,"Use "+target.label(),true,this::save);else Design.button(footer,"Use Math instead",false,()->respond(FALLBACK,0));}
 private void choose(){if(!current()||!hasWindowFocus()||!stop())return;String[] labels=ObjectTarget.LABELS.toArray(new String[0]);choices=SleepPicker.choices(this,"Object to find",labels,ObjectTarget.INDICES.indexOf(target.index),index->{target=new ObjectTarget(ObjectTarget.INDICES.get(index));hold=new ObjectHold(target);detected=false;status="Camera stays off until you start.";error="";render();});}
 private void startPressed(){if(!current()||!hasWindowFocus())return;error="";ObjectCameraAccess.Status permission=ObjectCameraAccess.status(this);if(permission==ObjectCameraAccess.Status.READY){begin();return;}if(permission==ObjectCameraAccess.Status.UNSUPPORTED){error="A rear camera is required. Use Math instead.";render();return;}try{ObjectCameraAccess.request(this);}catch(RuntimeException unavailable){error="Camera permission settings could not open. Use Math or retry.";render();}}
 private void begin(){if(!current()||!hasWindowFocus()||ObjectCameraAccess.status(this)!=ObjectCameraAccess.Status.READY)return;if(!stop()){error="Camera cleanup could not be confirmed. Return and use Math.";render();return;}long ticket=++generation;detected=false;hold.reset();try{camera=new ObjectCamera(this);started=SystemClock.elapsedRealtime();status="Loading the local model. Keep "+target.label()+" centered.";camera.start(new ObjectCamera.Listener(){public void frame(float[] scores,long captured){if(ticket!=generation||camera==null||!current()||!hasWindowFocus())return;if(ObjectCameraAccess.status(ObjectRecognitionActivity.this)!=ObjectCameraAccess.Status.READY){stop();error="Camera access changed. Allow it or use Math.";render();return;}long now=SystemClock.elapsedRealtime();if(hold.frame(scores,captured,now)){if(mode.equals("challenge"))respond(RESULT_OK,captured);else{stop();detected=true;status="Model target detected in this test. Save the selected object if suitable.";render();}return;}int best=0;for(int n=1;n<scores.length;n++)if(scores[n]>scores[best])best=n;status=best==target.index?"Hold steady · "+hold.progress()+"%":"Looking for "+target.label()+" · selected score "+Math.round(scores[target.index]*100)+"%";if(live!=null)live.setText(status);}public void error(String message){if(ticket!=generation||!current())return;stop();error=message;status="Camera stopped";render();}});render();}catch(RuntimeException unavailable){stop();error=unavailable.getMessage()==null?"Object recognition could not start. Use Math.":unavailable.getMessage();render();}}
 private boolean stop(){generation++;if(hold!=null)hold.reset();if(camera==null)return true;boolean closed=camera.close();if(closed)camera=null;return closed;}
 private void save(){if(!mode.equals("configure")||!current()||!hasWindowFocus()||!stop())return;try{setResult(RESULT_OK,new Intent().putExtra("request",request).putExtra("objectTarget",ObjectTargetJson.encode(target).toString()));finish();}catch(JSONException impossible){error="Object settings could not be returned.";render();}}
 private void respond(int result,long captured){if(!mode.equals("challenge")||!current()||!hasWindowFocus())return;if(!stop()){error="Camera cleanup could not be confirmed. Return and choose Math from the alarm.";render();return;}setResult(result,new Intent().putExtra("run",run).putExtra("unit",unit).putExtra("request",request).putExtra("targetKey",target.key()).putExtra("captured",captured));finish();}
 private void back(){stop();setResult(RESULT_CANCELED);finish();}
 @Override protected void onResume(){super.onResume();resumed=true;if(!current()){finish();return;}verify.run();render();}
 @Override protected void onPause(){resumed=false;handler.removeCallbacks(verify);if(choices!=null)choices.dismiss();stop();status="Camera paused. Tap Start for a new attempt.";super.onPause();}
 @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] results){super.onRequestPermissionsResult(code,permissions,results);if(code==ObjectCameraAccess.REQUEST){status=ObjectCameraAccess.status(this)==ObjectCameraAccess.Status.READY?"Camera access allowed. Tap Start object camera when ready.":"Camera access was not allowed. Use Math or allow access in settings.";if(resumed)render();}}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);else if(camera!=null){stop();status="Camera paused when this screen lost focus. Tap Start again.";if(resumed)render();}}
 @Override protected void onSaveInstanceState(Bundle saved){super.onSaveInstanceState(saved);try{saved.putString("objectTarget",ObjectTargetJson.encode(target).toString());}catch(JSONException ignored){}saved.putString("error",error);}
 @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);if(choices!=null)choices.dismiss();stop();super.onDestroy();}
}
